// Original QuickReply payload lives on the webhook node. Guard so testing a
// single node in isolation doesn't hard-crash.
let body = {};
try {
  body = $('QuickReply Webhook').first().json.body || {};
} catch (e) {
  const inp = $input.first();
  body = (inp && inp.json && (inp.json.body || inp.json)) || {};
}

const phone = body.phone || '';
const name = body.name || 'Customer';
const msgId = body.id || '';
const msgTime = Number(body.msg_time) || Date.now();
const payload = body.payload || {};
const text = payload.text || '';

// ---- Classify the message (confirmed from prod cloud-run logs) ----
//  text        -> _type USER_TEXT, has payload.text
//  image       -> _type USER_FILE, contentType image/jpeg
//  audio/voice -> _type USER_FILE, contentType audio/ogg, audioText ""
//  button tap  -> _type USER_LIST_REPLY / USER_BUTTON_REPLY
const ptype = String(payload._type || '').toUpperCase();
const contentType = String(payload.contentType || '').toLowerCase();
const hasText = !!(text && String(text).trim());

// MEDIA = any uploaded file: image, audio voice-note, report, document.
const isMedia = ptype === 'USER_FILE'
  || (!hasText && ptype && ptype !== 'USER_TEXT')
  || (!hasText && (contentType.startsWith('image/') || contentType.startsWith('audio/')));
let mediaKind = 'text';
if (isMedia) {
  if (contentType.startsWith('image/')) mediaKind = 'image';
  else if (contentType.startsWith('audio/')) mediaKind = 'audio';
  else mediaKind = 'file';
}
const mediaPath = payload.path || '';

// AUTOMATION / TEMPLATE triggers the AI must NOT answer — QuickReply's own flows
// already handle these (e.g. the Health Score CTA sends its link automatically).
// Add new predefined-button texts to AUTOMATION_TRIGGERS (matched case-insensitive).
const AUTOMATION_TRIGGERS = [
  'check my free health score',
  'check free healthscore',
  'i want my detailed healthscore',
  'mujhe vaji bati or kern drops chahiye'
];
const textLc = String(text || '').toLowerCase().trim();
const isTriggerText = AUTOMATION_TRIGGERS.some(t => textLc.includes(t));
const isButtonReply = ptype === 'USER_LIST_REPLY' || ptype === 'USER_BUTTON_REPLY';
const isAutomation = isTriggerText || isButtonReply;

// The AI answers ONLY real typed questions. Skip media + automation/button messages.
const skipAi = isMedia || isAutomation;
let skipReason = '';
if (isMedia) skipReason = 'media_' + mediaKind;
else if (isButtonReply) skipReason = 'button_reply';
else if (isTriggerText) skipReason = 'automation_trigger';

return [{
  json: {
    phone,
    name,
    msgId,
    msgTime,
    text,
    msgType: ptype,
    isMedia,
    mediaKind,
    mediaPath,
    isAutomation,
    skipAi,
    skipReason,
    convId: phone.replace(/[^0-9]/g, ''),   // matches CF qrConvId()
    savedAt: new Date().toISOString()
  }
}];

const RESUME_AFTER_SILENCE_MS = 30 * 60 * 1000; // human-silence before AI resumes

// This message's own trigger time (from the webhook). No static data — the whole
// decision is derived from the durable Firestore messages, so it works the same in
// test and production executions.
const src = $('Extract Message Details').first().json;
const phone = src.phone;
const name = src.name || 'Customer';
const myMsgTime = Number(src.msgTime) || 0;

// ---- per-number lists (global 'off' already short-circuited by "AI Enabled?") ----
let mode = 'on';
let testNumbers = ['+917300978845', '+918756112227'];
let blockedNumbers = [];
const toList = (v) => {
  if (!v) return [];
  const raw = Array.isArray(v) ? v.join(',') : String(v);
  return raw.split(',').map(s => s.trim()).filter(Boolean);
};
try {
  const cfg = $('Get AI Config').first().json;
  if (cfg && typeof cfg.mode === 'string' && cfg.mode.trim()) mode = cfg.mode.trim().toLowerCase();
  const tn = toList(cfg && cfg.testNumbers);
  if (tn.length) testNumbers = tn;
  blockedNumbers = toList(cfg && cfg.blockedNumbers);
} catch (e) {}

if (blockedNumbers.includes(phone)) return [{ json: { phone, name, shouldProcess: false, reason: 'ai_blocked_number' } }];
if (mode === 'off') return [{ json: { phone, name, shouldProcess: false, reason: 'ai_paused_global' } }];
if (mode === 'test' && !testNumbers.includes(phone)) return [{ json: { phone, name, shouldProcess: false, reason: 'ai_test_mode_only' } }];

// ---- read messages from conversations/{convId}/messages ----
// customer msg = direction 'in' | AI msg = out+text | human msg = out+AGENT_PLACEHOLDER
let items = [];
try { items = $('Fetch Conversation History').all(); } catch (e) { items = []; }
const tval = m => Number(m.msgTime) || new Date(m.createdAt || 0).getTime();
// The AI sends via ONE fixed QuickReply agent account; a human takeover comes from a
// DIFFERENT agent account. Distinguish by agentId (robust — no timing race).
const AI_AGENT_IDS = new Set(['u9ocdFtszn6BAXa7L_ag']);  // <- AI's own QuickReply send account(s)
let latestInboundAt = 0, lastAiAt = 0;
const humanCandidates = [];
for (const it of items) {
  const m = it.json; if (!m) continue;
  const t = tval(m);
  if (m.direction === 'in') { latestInboundAt = Math.max(latestInboundAt, t); continue; }
  if (m.direction === 'out') {
    const isAi = !!m.text && !m.placeholder && m._type !== 'AGENT_PLACEHOLDER' && m._type !== 'BOT_PLACEHOLDER';
    if (isAi) { lastAiAt = Math.max(lastAiAt, t); if (m.agentId) AI_AGENT_IDS.add(m.agentId); }
    // human candidate = AGENT placeholder, not automation-tagged
    else if (m._type === 'AGENT_PLACEHOLDER' && !m.automationBy) humanCandidates.push({ t, agentId: m.agentId || '' });
  }
}
// Genuine human takeover = AGENT placeholder from an agent that is NOT the AI's own account.
let lastHumanAt = 0;
for (const hc of humanCandidates) {
  if (!AI_AGENT_IDS.has(hc.agentId)) lastHumanAt = Math.max(lastHumanAt, hc.t);
}

// ---- DEBOUNCE (Firestore-based): if a newer customer message arrived during the
//      wait, let THAT execution answer the whole batch — this one bows out. ----
if (latestInboundAt > myMsgTime) {
  return [{ json: { phone, name, shouldProcess: false, reason: 'newer_message_wins', myMsgTime, latestInboundAt } }];
}

// ---- HANDOFF: a human agent is actively handling this chat ----
// Once a human agent has sent ANYTHING in the last RESUME window, the AI backs off —
// even if an in-flight AI reply happened to land after the human's message. The AI
// resumes only after the human has been quiet for the whole window.
const now = Date.now();
const humanActive = lastHumanAt > 0 && (now - lastHumanAt) < RESUME_AFTER_SILENCE_MS;
if (humanActive) {
  return [{ json: { phone, name, shouldProcess: false, reason: 'human_active', minsSinceHuman: Math.round((now - lastHumanAt) / 60000) } }];
}

// ---- already answered? ANY reply (AI text or a CF Bot/Agent placeholder) newer
//      than the latest customer message => this / a duplicate execution bows out. ----
// already answered = an actual AI reply or a genuine human reply after the latest
// customer message — NOT a QuickReply automation/bot template (those don't answer the query).
const answeredAt = Math.max(lastAiAt, lastHumanAt);
if (latestInboundAt > 0 && latestInboundAt <= answeredAt) {
  return [{ json: { phone, name, shouldProcess: false, reason: 'already_answered' } }];
}

return [{ json: { phone, name, shouldProcess: true, reason: 'process', resumedFromHuman: (lastHumanAt > 0 && lastHumanAt >= lastAiAt) } }];

const decide = $('Decide Process').first().json;
const phone = decide.phone;
const name = decide.name || 'Customer';

let items = [];
try { items = $('Fetch Conversation History').all(); } catch (e) { items = []; }
const tval = m => Number(m.msgTime) || new Date(m.createdAt || 0).getTime();
const evs = items.map(i => i.json).filter(m => m && (m.msgTime || m.createdAt))
  .map(m => ({ ...m, _t: tval(m) })).sort((a, b) => a._t - b._t);

const isAiMsg = m => m.direction === 'out' && !!m.text && !m.placeholder && m._type !== 'AGENT_PLACEHOLDER' && m._type !== 'BOT_PLACEHOLDER';
const isHumanMsg = m => m.direction === 'out' && (m._type === 'AGENT_PLACEHOLDER' || (m.placeholder && !m.text));

let lastAiAt = 0, lastHumanAt = 0;
for (const m of evs) {
  if (isAiMsg(m)) lastAiAt = Math.max(lastAiAt, m._t);
  else if (isHumanMsg(m)) lastHumanAt = Math.max(lastHumanAt, m._t);
}
const cutoff = Math.max(lastAiAt, lastHumanAt);
const resumedFromHuman = lastHumanAt > 0 && lastHumanAt >= lastAiAt;

// current turn = inbound user messages not yet answered
const unanswered = evs.filter(m => m.direction === 'in' && m._t > cutoff);
let newMsgText = unanswered.map(m => m.text || '').filter(Boolean).join('\n');
// Fallbacks so Gemini never receives an empty user message:
if (!newMsgText) {
  const lastUser = [...evs].reverse().find(m => m.direction === 'in' && m.text);
  if (lastUser) newMsgText = lastUser.text || '';
}
if (!newMsgText) {
  try { newMsgText = ($('Extract Message Details').first().json.text || '').trim(); } catch (e) {}
}

// transcript for context (human-agent turns are text-less; flagged via note below)
const history = [];
for (const m of evs) {
  if (m.direction === 'in') { if (m._t > cutoff) continue; history.push({ role: 'user', content: m.text || '' }); }
  else if (isAiMsg(m)) history.push({ role: 'assistant', content: m.text || '' });
}
const recentHistory = history.slice(-20);

const isFirstContact = !history.some(h => h.role === 'assistant');

// ---- TIME AWARENESS: use the customer's OWN message time (msg_time), not Date.now() ----
let curMsgTime = 0;
if (unanswered.length) curMsgTime = unanswered[unanswered.length - 1]._t;
if (!curMsgTime) { const lu = [...evs].reverse().find(m => m.direction === 'in'); if (lu) curMsgTime = lu._t; }
if (!curMsgTime) { try { curMsgTime = Number($('Extract Message Details').first().json.msgTime) || 0; } catch (e) {} }
if (!curMsgTime) curMsgTime = Date.now();

const istNow = new Date(curMsgTime + (5.5 * 60 * 60 * 1000));
const H = istNow.getUTCHours();
const Min = istNow.getUTCMinutes();
const clock = (((H + 11) % 12) + 1) + ':' + String(Min).padStart(2, '0') + ' ' + (H < 12 ? 'AM' : 'PM') + ' IST';
let partOfDay = 'night';
if (H >= 5 && H < 12) partOfDay = 'morning';
else if (H >= 12 && H < 17) partOfDay = 'afternoon';
else if (H >= 17 && H < 21) partOfDay = 'evening';
const totalMinutes = H * 60 + Min;
const isOfficeHours = totalMinutes >= (9 * 60 + 30) && totalMinutes < (18 * 60 + 30);

// gap since the customer's PREVIOUS inbound message (how long they were away)
const firstUnansweredAt = unanswered.length ? unanswered[0]._t : curMsgTime;
let prevInboundAt = 0;
for (const m of evs) { if (m.direction === 'in' && m._t < firstUnansweredAt) prevInboundAt = Math.max(prevInboundAt, m._t); }
const gapMs = prevInboundAt ? (firstUnansweredAt - prevInboundAt) : 0;
function fmtGap(ms) {
  if (!ms) return 'first message / no prior';
  const min = Math.round(ms / 60000);
  if (min < 1) return 'just now';
  if (min < 60) return min + ' min ago';
  const hr = Math.round(min / 60);
  if (hr < 24) return hr + ' hr ago';
  const d = Math.round(hr / 24);
  return d + ' day' + (d > 1 ? 's' : '') + ' ago';
}
const gapLabel = fmtGap(gapMs);

let basePrompt = 'You are Ananya, a Health Expert at SehatUP.';
try {
  const docData = $('Get a document').first().json;
  if (docData && docData.body && docData.body.content && Array.isArray(docData.body.content)) {
    const extracted = docData.body.content
      .map(b => b.paragraph && b.paragraph.elements
        ? b.paragraph.elements.map(e => (e.textRun && e.textRun.content) ? e.textRun.content : '').join('')
        : '')
      .join('').trim();
    if (extracted) basePrompt = extracted;
  }
} catch (e) { console.log('Could not read Google Doc, using default prompt:', e.message); }

const conversationContext = recentHistory.map(h => h.content).join(' ').toLowerCase();
const hasGreetingInHistory = conversationContext.includes('main ananya hoon') || conversationContext.includes('health expert at sehatup');

let systemPrompt = basePrompt
  + '\n\nCONTEXT:\nFirst contact: ' + (isFirstContact ? 'YES' : 'NO')
  + '\nCurrent time (customer message, IST): ' + clock + ' (' + partOfDay + ')'
  + '\nOffice hours: ' + (isOfficeHours ? 'OPEN' : 'CLOSED')
  + '\nTime since customer\'s previous message: ' + gapLabel
  + '\nCustomer name: ' + name
  + '\nGreeting already sent: ' + (hasGreetingInHistory ? 'YES' : 'NO')
  + '\n\nCRITICAL ANTI-SPAM RULES:\n'
  + '1. If "Greeting already sent: YES", NEVER send greeting again. Jump straight to answering the question.\n'
  + '2. If conversation history shows you already introduced yourself as Ananya, do NOT repeat introduction.\n'
  + '3. Only greet if: First contact: YES AND Greeting already sent: NO AND no assistant messages in history.\n'
  + '4. For follow-up questions, respond directly without any greeting or introduction.'
  + '\n5. Agar aapne pichle assistant message mein already free consultation/doctor-pitch wala paragraph bheja hai, to usko word-for-word ya near-identical dobara mat bhejo - short naya angle do ya seedha agla step (jaise time confirm karna) pucho.';

systemPrompt += '\n\nTIME AWARENESS: The times in CONTEXT are the real IST time of the customer\'s message (not "now"). Use them naturally: if it is late night, suggest a next-day consultation slot; if office hours are CLOSED, say the team will call during working hours (9:30am-6:30pm) instead of promising an immediate call; if the customer is returning after a long gap, continue warmly without repeating the full introduction. Do NOT open with good morning/afternoon/evening.';

if (resumedFromHuman) {
  systemPrompt += '\n\nHANDOFF NOTE: A human support agent was chatting with this customer and has now gone quiet, so you are taking over again. You CANNOT see the human agent\'s messages. Read the customer\'s latest message(s), avoid repeating earlier greetings/pitches, and continue helpfully from the current point.';
}

const messages = [
  { role: 'system', content: systemPrompt },
  ...recentHistory.map(h => ({ role: h.role, content: h.content })),
  { role: 'user', content: newMsgText }
];

// ---- DEBUG: exactly what history the AI fetched, in sequence, and what it got ----
const _debug = {
  fetchedMessages: evs.length,
  time: clock + ' ' + partOfDay + ' | office=' + (isOfficeHours ? 'OPEN' : 'CLOSED') + ' | gap=' + gapLabel,
  sequence: evs.map(m => `${new Date(m._t).toISOString().slice(11, 19)} | ${m.direction || '?'} | ${(m._type || '').replace('AGENT_', '')} | ${(m.text || m.placeholder || '').slice(0, 50)}`),
  historyToAI: recentHistory.map(h => `${h.role}: ${(h.content || '').slice(0, 50)}`),
  currentTurn: newMsgText,
  isFirstContact,
  resumedFromHuman,
};
console.log('[Build AI Prompt] fetched=' + evs.length + ' time=' + _debug.time + ' history=' + JSON.stringify(_debug.sequence));

return [{ json: { phone, name, messages, newMsgText, isFirstContact, hasGreetingInHistory, resumedFromHuman, clock, partOfDay, isOfficeHours, gapLabel, systemPromptLength: systemPrompt.length, _debug } }];

const geminiResponse = $input.first().json;
const _parts = geminiResponse.candidates?.[0]?.content?.parts || [];
// This tuned model emits a "think"/reasoning part first and the REAL reply as the
// LAST text part — so take the last non-empty part, not parts[0].
let aiText = '';
for (let i = _parts.length - 1; i >= 0; i--) {
  const tx = _parts[i] && _parts[i].text ? _parts[i].text.trim() : '';
  if (tx) { aiText = tx; break; }
}
aiText = aiText.replace(/^\s*(think|thought|reasoning)\b[\s\S]*?\n\n/i, '').trim();  // strip any leading reasoning block
if (!aiText) aiText = 'Sorry, kuch problem aa gayi. Please dobara try karein.';

const buildData = $('Build AI Prompt').first().json || {};
let phone = buildData.phone;
if (!phone) { try { phone = $('Decide Process').first().json.phone; } catch (e) {} }
if (!phone) throw new Error('Extract AI Response: phone missing. buildData=' + JSON.stringify(buildData));
const name = buildData.name || 'Customer';
const newMsgText = buildData.newMsgText || '';

// ---- Have we already greeted? — authoritative, from the REAL conversation history.
//      (The fine-tuned model ignores the "greet once" rule, so we control it here.) ----
let greetedBefore = false;
try {
  const items = $('Fetch Conversation History').all();
  for (const it of items) {
    const m = it && it.json; if (!m) continue;
    const txt = (m.text || '').toLowerCase();
    if (m.direction === 'out' && (m.text || m.placeholder)) greetedBefore = true;   // a prior bot/agent reply
    if (txt.includes('ananya') && txt.includes('sehat')) greetedBefore = true;      // intro already sent
  }
} catch (e) {}

// ---- Sanitize + strip ANY model-generated intro (kept: time greetings, titles) ----
function sanitizeReply(t) {
  if (!t) return '';
  let s = String(t);
  s = s.replace(/\b(good\s*(morning|afternoon|evening|noon)|gud\s*(mrng|morning|evening|evng)|shubh\s*(prabhat|sandhya)|subh\s*prabhat)\b[\s,!.-]*/gi, '');
  s = s.replace(/\b(ma'?am|madam|mem(sahib|saheb)?|sir(ji|jee)?|bhai(ya)?|bro(ther)?)\b/gi, 'ji');
  s = s.replace(/hello\s*ji[\s,!.]*/gi, '');
  s = s.replace(/\bma?i?n?\s*ananya\s+baat\s+kar\s+rah[iy]\s*hu?n?\s*,?\s*sehat\s*up\s*se[\s,.!]*/gi, '');
  s = s.replace(/\bma?i?n?\s*ananya\s+(hu|hoon)\b[\s,.!]*/gi, '');
  s = s.replace(/\b(ji)(\s*,?\s*ji\b)+/gi, 'ji');
  s = s.replace(/[ \t]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n');
  s = s.replace(/^[\s,.:;!-]+/, '').replace(/[ \t]+([,.!?])/g, '$1').trim();
  return s;
}
aiText = sanitizeReply(aiText);

// ---- Add the introduction EXACTLY ONCE, only on genuine first contact ----
if (!greetedBefore) {
  aiText = 'Hello ji, mai Ananya baat kar rahi hu SehatUP se. ' + (aiText || 'mai aapki kya help kar sakti hu?');
}
if (!aiText) aiText = 'ji, bataiye mai aapki kya help kar sakti hu?';

const docId = phone.replace(/[^0-9]/g, '');
return [{
  json: {
    phone,
    name,
    lastAiReply: aiText,
    lastUserMessage: newMsgText,
    docId,
    lastUpdated: new Date().toISOString()
  }
}];

// After the WhatsApp send: capture the id QuickReply returned (data.id) so the
// message doc is keyed by it — then the CF's forwarded SENT/DELIVERED/READ status
// callbacks update THIS doc in place instead of making a "Bot replied" placeholder.
const send = $input.first().json || {};
let sentId = null;
const cands = [send.id, send.messageId, send.message_id,
  send.data && send.data.id, send.data && send.data.messageId,
  send.message && send.message.id, send.result && send.result.id];
for (const c of cands) { if (c) { sentId = String(c); break; } }

const ai = $('Extract AI Response').first().json;
const now = Date.now();
const convId = String(ai.phone || '').replace(/[^0-9]/g, '');
const msgId = sentId || ('local_' + now + '_' + Math.floor(Math.random() * 1e6));

console.log('QR send response (first 200):', JSON.stringify(send).slice(0, 200), '| id:', sentId);

return [{
  json: {
    convId,
    msgId,
    id: msgId,
    phone: ai.phone,
    direction: 'out',
    messageBy: 'AI',
    _type: 'AGENT_TEXT',
    text: ai.lastAiReply,
    status: 'SENT',
    msgTime: now,
    createdAt: new Date().toISOString()
  }
}];

